import{_ as p,a0 as l,w as o,s as d,ao as r,I as i,x as a,a1 as n,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const m=JSON.parse('{"title":"PHP PDO 简单教程 | LCTT x X-CMD","titleTemplate":false,"description":"PHP PDO 简单教程 | LCTT (201905) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"PHP PDO 简单教程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"PHP PDO 简单教程 | LCTT (201905) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201905/20180429 The Easiest PDO Tutorial (Basics)","title":"PHP PDO 简单教程","tag":"201905","desc":""},"relativePath":"201905/20180429 The Easiest PDO Tutorial (Basics).md","filePath":"[post].md"}'),h={name:"201905/20180429 The Easiest PDO Tutorial (Basics).md"};function c(g,s,u,b,k,P){const e=l("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="php-pdo-简单教程" tabindex="-1">PHP PDO 简单教程 <a class="header-anchor" href="#php-pdo-简单教程" aria-label="Permalink to “PHP PDO 简单教程”">​</a></h1><p><img src="http://www.theitstuff.com/wp-content/uploads/2018/04/php-language.jpg" alt=""></p><p>大约 80% 的 Web 应用程序由 PHP 提供支持。类似地，SQL 也是如此。PHP 5.5 版本之前，我们有用于访问 MySQL 数据库的 mysql_ 命令，但由于安全性不足，它们最终被弃用。</p><p>弃用这件事是发生在 2013 年的 PHP 5.5 上，我写这篇文章的时间是 2018 年，PHP 版本为 7.2。mysql_ 的弃用带来了访问数据库的两种主要方法：mysqli 和 PDO 库。</p><p>虽然 mysqli 库是官方指定的，但由于 mysqli 只能支持 mysql 数据库，而 PDO 可以支持 12 种不同类型的数据库驱动程序，因此 PDO 获得了更多的赞誉。此外，PDO 还有其它一些特性，使其成为大多数开发人员的更好选择。你可以在下表中看到一些特性比较：</p><div class="table-wrap"><table><thead><tr><th></th><th>PDO</th><th>MySQLi</th></tr></thead><tbody><tr><td>数据库支持</td><td>12 种驱动</td><td>只有 MySQL</td></tr><tr><td>范例</td><td>OOP</td><td>过程 + OOP</td></tr><tr><td>预处理语句（客户端侧）</td><td>Yes</td><td>No</td></tr><tr><td>1命名参数</td><td>Yes</td><td>No</td></tr></tbody></table></div><p>现在我想对于大多数开发人员来说，PDO 是首选的原因已经很清楚了。所以让我们深入研究它，并希望在本文中尽量涵盖关于 PDO 你需要的了解的。</p><h3 id="连接" tabindex="-1">连接 <a class="header-anchor" href="#连接" aria-label="Permalink to “连接”">​</a></h3><p>第一步是连接到数据库，由于 PDO 是完全面向对象的，所以我们将使用 PDO 类的实例。</p><p>我们要做的第一件事是定义主机、数据库名称、用户名、密码和数据库字符集。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$host = &#39;localhost&#39;;</span></span>
<span class="line"><span>$db   = &#39;theitstuff&#39;;</span></span>
<span class="line"><span>$user = &#39;root&#39;;</span></span>
<span class="line"><span>$pass = &#39;root&#39;;</span></span>
<span class="line"><span>$charset = &#39;utf8mb4&#39;;</span></span>
<span class="line"><span>$dsn = &quot;mysql:host=$host;dbname=$db;charset=$charset&quot;;</span></span>
<span class="line"><span>$conn = new PDO($dsn, $user, $pass);</span></span></code></pre></div><p>之后，正如你在上面的代码中看到的，我们创建了 DSN 变量，DSN 变量只是一个保存数据库信息的变量。对于一些在外部服务器上运行 MySQL 的人，你还可以通过提供一个 <code>port=$port_number</code> 来调整端口号。</p><p>最后，你可以创建一个 PDO 类的实例，我使用了 <code>$conn</code> 变量，并提供了 <code>$dsn</code>、<code>$user</code>、<code>$pass</code> 参数。如果你遵循这些步骤，你现在应该有一个名为 <code>$conn</code> 的对象，它是 PDO 连接类的一个实例。现在是时候进入数据库并运行一些查询。</p><h3 id="一个简单的-sql-查询" tabindex="-1">一个简单的 SQL 查询 <a class="header-anchor" href="#一个简单的-sql-查询" aria-label="Permalink to “一个简单的 SQL 查询”">​</a></h3><p>现在让我们运行一个简单的 SQL 查询。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$tis = $conn-&gt;query(&#39;SELECT name, age FROM students&#39;);</span></span>
<span class="line"><span>while ($row = $tis-&gt;fetch())</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  echo $row[&#39;name&#39;].&quot;\\t&quot;;</span></span>
<span class="line"><span>  echo $row[&#39;age&#39;];</span></span>
<span class="line"><span>  echo &quot;&lt;br&gt;&quot;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这是使用 PDO 运行查询的最简单形式。我们首先创建了一个名为 <code>tis</code>（TheITStuff 的缩写 ）的变量，然后你可以看到我们使用了创建的 <code>$conn</code> 对象中的查询函数。</p><p>然后我们运行一个 <code>while</code> 循环并创建了一个 <code>$row</code> 变量来从 <code>$tis</code> 对象中获取内容，最后通过调用列名来显示每一行。</p><p>很简单，不是吗？现在让我们来看看预处理语句。</p><h3 id="预处理语句" tabindex="-1">预处理语句 <a class="header-anchor" href="#预处理语句" aria-label="Permalink to “预处理语句”">​</a></h3><p>预处理语句是人们开始使用 PDO 的主要原因之一，因为它提供了可以阻止 SQL 注入的语句。</p><p>有两种基本方法可供使用，你可以使用位置参数或命名参数。</p><h4 id="位置参数" tabindex="-1">位置参数 <a class="header-anchor" href="#位置参数" aria-label="Permalink to “位置参数”">​</a></h4><p>让我们看一个使用位置参数的查询示例。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$tis = $conn-&gt;prepare(&quot;INSERT INTO STUDENTS(name, age) values(?, ?)&quot;);</span></span>
<span class="line"><span>$tis-&gt;bindValue(1,&#39;mike&#39;);</span></span>
<span class="line"><span>$tis-&gt;bindValue(2,22);</span></span>
<span class="line"><span>$tis-&gt;execute();</span></span></code></pre></div><p>在上面的例子中，我们放置了两个问号，然后使用 <code>bindValue()</code> 函数将值映射到查询中。这些值绑定到语句问号中的位置。</p><p>我还可以使用变量而不是直接提供值，通过使用 <code>bindParam()</code> 函数相同例子如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$name=&#39;Rishabh&#39;; $age=20;</span></span>
<span class="line"><span>$tis = $conn-&gt;prepare(&quot;INSERT INTO STUDENTS(name, age) values(?, ?)&quot;);</span></span>
<span class="line"><span>$tis-&gt;bindParam(1,$name);</span></span>
<span class="line"><span>$tis-&gt;bindParam(2,$age);</span></span>
<span class="line"><span>$tis-&gt;execute();</span></span></code></pre></div><h3 id="命名参数" tabindex="-1">命名参数 <a class="header-anchor" href="#命名参数" aria-label="Permalink to “命名参数”">​</a></h3><p>命名参数也是预处理语句，它将值/变量映射到查询中的命名位置。由于没有位置绑定，因此在多次使用相同变量的查询中非常有效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$name=&#39;Rishabh&#39;; $age=20;</span></span>
<span class="line"><span>$tis = $conn-&gt;prepare(&quot;INSERT INTO STUDENTS(name, age) values(:name, :age)&quot;);</span></span>
<span class="line"><span>$tis-&gt;bindParam(&#39;:name&#39;, $name);</span></span>
<span class="line"><span>$tis-&gt;bindParam(&#39;:age&#39;, $age);</span></span>
<span class="line"><span>$tis-&gt;execute();</span></span></code></pre></div><p>你可以注意到，唯一的变化是我使用 <code>:name</code> 和 <code>:age</code> 作为占位符，然后将变量映射到它们。冒号在参数之前使用，让 PDO 知道该位置是一个变量，这非常重要。</p><p>你也可以类似地使用 <code>bindValue()</code> 来使用命名参数直接映射值。</p><h3 id="获取数据" tabindex="-1">获取数据 <a class="header-anchor" href="#获取数据" aria-label="Permalink to “获取数据”">​</a></h3><p>PDO 在获取数据时非常丰富，它实际上提供了许多格式来从数据库中获取数据。</p><p>你可以使用 <code>PDO::FETCH_ASSOC</code> 来获取关联数组，<code>PDO::FETCH_NUM</code> 来获取数字数组，使用 <code>PDO::FETCH_OBJ</code> 来获取对象数组。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$tis = $conn-&gt;prepare(&quot;SELECT * FROM STUDENTS&quot;);</span></span>
<span class="line"><span>$tis-&gt;execute();</span></span>
<span class="line"><span>$result = $tis-&gt;fetchAll(PDO::FETCH_ASSOC);</span></span></code></pre></div><p>你可以看到我使用了 <code>fetchAll</code>，因为我想要所有匹配的记录。如果只需要一行，你可以简单地使用 <code>fetch</code>。</p><p>现在我们已经获取了数据，现在是时候循环它了，这非常简单。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>foreach ($result as $lnu){</span></span>
<span class="line"><span>  echo $lnu[&#39;name&#39;];</span></span>
<span class="line"><span>  echo $lnu[&#39;age&#39;].&quot;&lt;br&gt;&quot;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>你可以看到，因为我请求了关联数组，所以我正在按名称访问各个成员。</p><p>虽然在定义希望如何传输递数据方面没有要求，但在定义 <code>$conn</code> 变量本身时，实际上可以将其设置为默认值。</p><p>你需要做的就是创建一个 <code>$options</code> 数组，你可以在其中放入所有默认配置，只需在 <code>$conn</code> 变量中传递数组即可。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$options = [</span></span>
<span class="line"><span>  PDO::ATTR_DEFAULT_FETCH_MODE =&gt; PDO::FETCH_ASSOC,</span></span>
<span class="line"><span>];</span></span>
<span class="line"><span>$conn = new PDO($dsn, $user, $pass, $options);</span></span></code></pre></div><p>这是一个非常简短和快速的 PDO 介绍，我们很快就会制作一个高级教程。如果你在理解本教程的任何部分时遇到任何困难，请在评论部分告诉我，我会在那你为你解答。</p><hr>`,46)),i("p",null,[s[1]||(s[1]=a("via: ",-1)),n(e,{href:"http://www.theitstuff.com/easiest-pdo-tutorial-basics"},{default:t(()=>[...s[0]||(s[0]=[a("http://www.theitstuff.com/easiest-pdo-tutorial-basics",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=a("作者：",-1)),n(e,{href:"http://www.theitstuff.com/author/reevkandari"},{default:t(()=>[...s[2]||(s[2]=[a("Rishabh Kandari",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),n(e,{href:"https://github.com/MjSeven"},{default:t(()=>[...s[4]||(s[4]=[a("MjSeven",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const T=p(h,[["render",c]]);export{m as __pageData,T as default};
